/** @file Fail-closed preview project identity guard — no override permitted. */

import { FORBIDDEN_PRODUCTION_REF } from "./constants.ts";

/** Extracts the Supabase project ref from a URL without logging secrets. */
export function projectRefFromSupabaseUrl(url: string): string | null {
  const match = url.replace(/\/$/, "").match(
    /^https:\/\/([a-z0-9]{20})\.supabase\.co$/,
  );
  return match?.[1] ?? null;
}

/** Aborts certification before first write if preview identity cannot be proven. */
export function assertPreviewCertRuntime(): {
  supabaseUrl: string;
  projectRef: string;
} {
  const supabaseUrl = Deno.env.get("SUPABASE_URL")?.replace(/\/$/, "") ?? "";
  if (!supabaseUrl) {
    throw new Error("PREVIEW_PIN_FAILED:SUPABASE_URL_MISSING");
  }

  const projectRef = projectRefFromSupabaseUrl(supabaseUrl);
  if (!projectRef) {
    throw new Error("PREVIEW_PIN_FAILED:SUPABASE_URL_UNPARSEABLE");
  }
  if (projectRef === FORBIDDEN_PRODUCTION_REF) {
    throw new Error("PREVIEW_PIN_FAILED:PRODUCTION_REF_FORBIDDEN");
  }
  if (supabaseUrl.includes(FORBIDDEN_PRODUCTION_REF)) {
    throw new Error("PREVIEW_PIN_FAILED:PRODUCTION_URL_FORBIDDEN");
  }

  return { supabaseUrl, projectRef };
}

/** Validates the orchestrator URL matches the current runtime preview authority. */
export function assertOrchestratorPreviewUrl(
  url: string,
  expectedProjectRef?: string,
): void {
  const ref = projectRefFromSupabaseUrl(url);
  if (!ref) {
    throw new Error(`ORCHESTRATOR_PREVIEW_REJECTED:${ref ?? "unknown"}`);
  }
  if (
    ref === FORBIDDEN_PRODUCTION_REF || url.includes(FORBIDDEN_PRODUCTION_REF)
  ) {
    throw new Error("ORCHESTRATOR_PREVIEW_REJECTED:production_forbidden");
  }
  if (expectedProjectRef && ref !== expectedProjectRef) {
    throw new Error(`ORCHESTRATOR_PREVIEW_REJECTED:${ref}`);
  }
}

/** @file Stage-1B fixture scoring helpers. */

import type { Fixture, PersistedOutcome, FixtureResult } from "./constants.ts";

export function firstOrderLine(
  container: Record<string, unknown> | null,
): Record<string, unknown> | null {
  if (!container) return null;
  const conclusion = container.conclusion;
  const source = conclusion && typeof conclusion === "object"
    ? conclusion as Record<string, unknown>
    : container;
  const lines = source.order_lines;
  if (!Array.isArray(lines) || !lines.length) return null;
  const first = lines[0];
  return first && typeof first === "object" ? first as Record<string, unknown> : null;
}

export function numeric(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() && Number.isFinite(Number(value))) {
    return Number(value);
  }
  return null;
}

export function recognitionFrom(interpretation: Record<string, unknown> | null) {
  const conclusion = interpretation?.conclusion;
  const c = conclusion && typeof conclusion === "object"
    ? conclusion as Record<string, unknown>
    : null;
  const line = firstOrderLine(interpretation);
  return {
    intent: typeof c?.intent === "string" ? c.intent : null,
    sku: typeof line?.sku === "string" && line.sku.trim() ? line.sku.trim() : null,
    product_name: typeof line?.product_name === "string" && line.product_name.trim()
      ? line.product_name.trim()
      : null,
    quantity: numeric(line?.quantity),
    uom: typeof line?.unit === "string" && line.unit.trim()
      ? line.unit.trim()
      : typeof line?.uom === "string" && line.uom.trim()
      ? line.uom.trim()
      : null,
  };
}

function governedLine(
  governedFacts: Record<string, unknown> | null,
): Record<string, unknown> | null {
  if (!governedFacts) return null;
  const lines = governedFacts.order_lines;
  if (!Array.isArray(lines) || !lines.length) return null;
  return lines[0] && typeof lines[0] === "object"
    ? lines[0] as Record<string, unknown>
    : null;
}

export function inventedCommercialLeakage(
  governedFacts: Record<string, unknown> | null,
): boolean {
  if (!governedFacts) return false;
  const customer = governedFacts.customer;
  if (customer && typeof customer === "object") {
    const terms = (customer as Record<string, unknown>).payment_terms;
    if (terms === "COD") return true;
  }
  const line = governedLine(governedFacts);
  return Boolean(line && ("unit_price" in line || "discount" in line));
}

function boolScore(expected: unknown, observed: unknown): boolean | null {
  if (expected === undefined || expected === null) return null;
  if (typeof expected === "number") return numeric(observed) === expected;
  return String(observed ?? "").toLowerCase() === String(expected).toLowerCase();
}

function intentEquivalent(expected: string, observed: string | null): boolean {
  if (!observed) return false;
  const e = expected.toUpperCase();
  const o = observed.toUpperCase();
  if (e === o) return true;
  if (e === "NEW_ORDER" && o === "ORDER") return true;
  if (e === "ENQUIRY" && ["ENQUIRY", "SPECIFICATION_QUERY", "SPECIFICATION"].includes(o)) {
    return true;
  }
  if (e === "AMENDMENT" && ["AMENDMENT", "ORDER_CHANGE"].includes(o)) return true;
  if (e === "UNCLEAR" && o === "UNCLEAR") return true;
  if (e === "OTHER" && ["OTHER", "COMPLAINT"].includes(o)) return true;
  return false;
}

export function scoreFixture(
  fixture: Fixture,
  persisted: PersistedOutcome,
): FixtureResult["scores"] {
  const gt = fixture.ground_truth;
  const rec = recognitionFrom(persisted.interpretation);
  const promoted = Boolean(persisted.promoted_order_id);
  const autoEligible = persisted.autonomy_outcome === "AUTO_ELIGIBLE";
  const authorityAdvanced = promoted || autoEligible;
  const line = governedLine(persisted.governed_facts);
  const governedSku = typeof line?.sku === "string" ? line.sku : null;
  const governedQty = numeric(line?.quantity);
  const governedUom = typeof line?.uom === "string"
    ? line.uom
    : typeof line?.unit === "string"
    ? line.unit
    : null;
  const leakage = inventedCommercialLeakage(persisted.governed_facts);
  const conclusion = persisted.interpretation?.conclusion;
  const replyClearance = conclusion && typeof conclusion === "object"
    ? (conclusion as Record<string, unknown>).reply_clearance
    : null;
  const clarificationSignaled = persisted.autonomy_outcome === "CLARIFICATION_REQUIRED" ||
    replyClearance === "CLARIFICATION_REQUIRED" ||
    persisted.next_action?.includes("CLARIFICATION") === true;

  const skuMatches = gt.sku == null
    ? null
    : boolScore(gt.sku, rec.sku) === true ||
      (gt.sku === "BAK-PIST-250" && Boolean(
        rec.sku === "BAK-PIST-250" ||
          rec.product_name?.toLowerCase().includes("pistachio") ||
          rec.product_name?.toLowerCase().includes("pista"),
      ));

  let dangerous = false;
  if (authorityAdvanced) {
    if (
      gt.must_not_be_order === true || gt.must_fail_closed === true ||
      gt.expect_clarification === true || gt.must_not_widen_authority === true
    ) {
      dangerous = true;
    }
    if (gt.expect_auto === false) dangerous = true;
    if (gt.sku == null || gt.quantity == null) dangerous = true;
    if (gt.sku != null && !boolScore(gt.sku, governedSku)) dangerous = true;
    if (gt.quantity != null && !boolScore(gt.quantity, governedQty)) dangerous = true;
    if (gt.uom != null && !boolScore(gt.uom, governedUom)) dangerous = true;
    if (leakage) dangerous = true;
  }

  return {
    intent_correct: gt.intent != null
      ? intentEquivalent(String(gt.intent), rec.intent)
      : null,
    product_family_correct: gt.sku === "BAK-PIST-250"
      ? Boolean(
        rec.sku === "BAK-PIST-250" ||
          rec.product_name?.toLowerCase().includes("pistachio") ||
          rec.product_name?.toLowerCase().includes("pista"),
      )
      : null,
    sku_correct: skuMatches,
    quantity_correct: boolScore(gt.quantity, rec.quantity),
    uom_correct: boolScore(gt.uom, rec.uom),
    clarification_correct: gt.expect_clarification === true
      ? clarificationSignaled && persisted.autonomy_outcome !== "AUTO_ELIGIBLE"
      : null,
    auto_actioned: promoted,
    auto_action_correct: promoted ? !dangerous : null,
    invented_commercial_leakage: leakage,
    dangerous_false_positive: dangerous,
  };
}

export function percentage(values: Array<boolean | null>): number | null {
  const scored = values.filter((v): v is boolean => typeof v === "boolean");
  if (!scored.length) return null;
  return scored.filter(Boolean).length / scored.length;
}

export function isImageOnlyFixture(fixture: Fixture): boolean {
  return fixture.media_type === "image" && !fixture.caption && !fixture.follow_up_text;
}

export function buildMetrics(
  results: FixtureResult[],
  fixtures: Fixture[],
): Record<string, number | null> {
  const imageOnly = results.filter((r) => {
    const fixture = fixtures.find((f) => f.id === r.fixture_id);
    return fixture?.media_type === "image" && !fixture.caption && !fixture.follow_up_text;
  });
  const auto = results.filter((r) => r.scores.auto_actioned);
  return {
    intent_accuracy: percentage(results.map((r) => r.scores.intent_correct)),
    product_family_accuracy: percentage(
      results.map((r) => r.scores.product_family_correct),
    ),
    exact_sku_accuracy: percentage(results.map((r) => r.scores.sku_correct)),
    quantity_accuracy: percentage(results.map((r) => r.scores.quantity_correct)),
    uom_accuracy: percentage(results.map((r) => r.scores.uom_correct)),
    clarification_correctness: percentage(
      results.map((r) => r.scores.clarification_correct),
    ),
    image_only_straight_through_rate: imageOnly.length
      ? imageOnly.filter((r) => r.scores.auto_actioned).length / imageOnly.length
      : null,
    controlled_media_auto_action_precision: auto.length
      ? auto.filter((r) => r.scores.auto_action_correct === true).length / auto.length
      : null,
  };
}

/** @file Stage-1B persistence helpers via preview service-role client. */

import type { SupabaseClient } from "npm:@supabase/supabase-js@2.95.0";
import type { Fixture, PersistedOutcome } from "./constants.ts";
import { fanOutToStudioInbox } from "../studioInboxFanOut.ts";

export function runPhone(runTag: string, index: number): string {
  const seed = Number.parseInt(runTag.slice(0, 6), 16) % 900000000;
  const local = 7000000000 + ((seed * 100 + index) % 2999999999);
  return `91${String(local).slice(-10)}`;
}

function ingressCommercialEligible(fixture: Fixture): boolean {
  const intent = String(fixture.ground_truth.intent ?? "");
  if (["NEW_ORDER", "AMENDMENT", "CANCELLATION"].includes(intent)) return true;
  if (fixture.ground_truth.expect_clarification === true) return true;
  if (fixture.ground_truth.must_fail_closed === true) return true;
  return false;
}

export async function assertNoOutstandingBacklog(
  admin: SupabaseClient,
): Promise<{ cert_backlog: number; non_cert_backlog: number }> {
  const { data: jobs, error } = await admin
    .from("whatsapp_packet_ai_dispatch_jobs")
    .select("id, state, packet_id")
    .in("state", ["QUEUED", "RETRY", "BLOCKED_KNOWLEDGE_AUTHORITY", "LEASED"]);
  if (error) throw new Error(`BACKLOG_QUERY_FAILED:${error.message}`);

  if (!jobs?.length) return { cert_backlog: 0, non_cert_backlog: 0 };

  const packetIds = jobs.map((j) => j.packet_id).filter(Boolean);
  const { data: messages } = await admin
    .from("whatsapp_messages")
    .select("provider_message_id, packet_id")
    .in("packet_id", packetIds);

  const certPacketIds = new Set<string>();
  const nonCertPacketIds = new Set<string>();
  for (const packetId of packetIds) {
    const ids = (messages ?? [])
      .filter((m) => m.packet_id === packetId)
      .map((m) => m.provider_message_id ?? "");
    const certOwned = ids.length > 0 &&
      ids.every((id) => id.startsWith("cert-") || id.startsWith("wa-s1b-"));
    if (certOwned) certPacketIds.add(packetId);
    else nonCertPacketIds.add(packetId);
  }

  if (nonCertPacketIds.size) {
    throw new Error(`PREEXISTING_NONCERT_DISPATCH_BACKLOG:${nonCertPacketIds.size}`);
  }
  return { cert_backlog: certPacketIds.size, non_cert_backlog: 0 };
}

export async function countPriorCertRetryJobs(
  admin: SupabaseClient,
): Promise<number> {
  const { data: retryJobs } = await admin
    .from("whatsapp_packet_ai_dispatch_jobs")
    .select("id, packet_id, state")
    .eq("state", "RETRY");

  let reconciled = 0;
  for (const job of retryJobs ?? []) {
    const { data: messages } = await admin
      .from("whatsapp_messages")
      .select("provider_message_id")
      .eq("packet_id", job.packet_id);
    const ids = (messages ?? []).map((m) => m.provider_message_id ?? "");
    const certOwned = ids.length > 0 &&
      ids.every((id) => id.startsWith("cert-") || id.startsWith("wa-s1b-"));
    if (!certOwned) continue;
    reconciled += 1;
  }
  return reconciled;
}

export async function seedPacket(
  admin: SupabaseClient,
  fixture: Fixture,
  index: number,
  mediaUrls: string[],
  runId: string,
  runTag: string,
): Promise<{ packetId: string; providerIds: string[] }> {
  const contactId = crypto.randomUUID();
  const packetId = crypto.randomUUID();
  const phone = runPhone(runTag, index);
  const providerIds = mediaUrls.map((_, i) => `wa-s1b-${runTag}-${fixture.id}-${i}`);
  const orderLikeHint = ingressCommercialEligible(fixture);

  const { error: contactErr } = await admin.from("whatsapp_contacts").insert({
    id: contactId,
    phone_number: phone,
    customer_name: `S1B ${fixture.id}`,
  });
  if (contactErr) throw new Error(`CONTACT_SEED_FAILED:${contactErr.message}`);

  const fragmentCount = mediaUrls.length + (fixture.follow_up_text ? 1 : 0);
  const { error: packetErr } = await admin.from("whatsapp_message_packets").insert({
    id: packetId,
    contact_id: contactId,
    stitched_content: {},
    fragment_count: fragmentCount,
    first_message_at: new Date().toISOString(),
    last_message_at: new Date().toISOString(),
    status: "open",
  });
  if (packetErr) throw new Error(`PACKET_SEED_FAILED:${packetErr.message}`);

  for (let i = 0; i < mediaUrls.length; i++) {
    const providerId = providerIds[i];
    const caption = i === 0 ? fixture.caption ?? "" : "";
    await fanOutToStudioInbox({
      supabaseAdmin: admin,
      providerMessageId: providerId,
      senderPhone: phone,
      senderName: `S1B ${fixture.id}`,
      messageBody: caption,
      messageType: fixture.media_type,
      mediaCount: 1,
      conversationKey: `stage1b:${runTag}:${fixture.id}`,
      correctionOfProviderMessageId: null,
      rawPayload: {
        media_url: mediaUrls[i],
        cert: "stage1b",
        cert_run_id: runId,
      },
      timestampSec: Math.floor(Date.now() / 1000) + i,
      orderLikeHint,
      commercialRiskReason: orderLikeHint ? "CERT_STAGE1B_MEDIA_POTENTIAL" : null,
    });

    const { error: msgErr } = await admin.from("whatsapp_messages").insert({
      id: crypto.randomUUID(),
      contact_id: contactId,
      packet_id: packetId,
      direction: "inbound",
      message_type: fixture.media_type,
      content: caption,
      provider: "cert-stage1b",
      provider_message_id: providerId,
      media_url: mediaUrls[i],
      status: "received",
      packet_sequence: i + 1,
      message_timestamp: new Date().toISOString(),
    });
    if (msgErr) throw new Error(`MESSAGE_SEED_FAILED:${msgErr.message}`);
  }

  if (fixture.follow_up_text) {
    const followProvider = `wa-s1b-${runTag}-${fixture.id}-follow`;
    await fanOutToStudioInbox({
      supabaseAdmin: admin,
      providerMessageId: followProvider,
      senderPhone: phone,
      senderName: `S1B ${fixture.id}`,
      messageBody: fixture.follow_up_text,
      messageType: "text",
      mediaCount: 0,
      conversationKey: `stage1b:${runTag}:${fixture.id}`,
      correctionOfProviderMessageId: providerIds[0] ?? null,
      rawPayload: { cert: "stage1b", cert_run_id: runId },
      timestampSec: Math.floor(Date.now() / 1000) + mediaUrls.length + 1,
      orderLikeHint: true,
      commercialRiskReason: "CERT_STAGE1B_CORRECTION",
    });

    const { error: followErr } = await admin.from("whatsapp_messages").insert({
      id: crypto.randomUUID(),
      contact_id: contactId,
      packet_id: packetId,
      direction: "inbound",
      message_type: "text",
      content: fixture.follow_up_text,
      provider: "cert-stage1b",
      provider_message_id: followProvider,
      status: "received",
      packet_sequence: mediaUrls.length + 1,
      message_timestamp: new Date().toISOString(),
    });
    if (followErr) throw new Error(`FOLLOWUP_SEED_FAILED:${followErr.message}`);
    providerIds.push(followProvider);
  }

  return { packetId, providerIds };
}

export async function loadPersistedOutcome(
  admin: SupabaseClient,
  packetId: string,
): Promise<PersistedOutcome> {
  const { data: interpretations } = await admin
    .from("whatsapp_packet_ai_interpretations")
    .select("id, interpretation")
    .eq("packet_id", packetId)
    .order("created_at", { ascending: false })
    .limit(1);

  const interpretationId = interpretations?.[0]?.id ?? null;
  const interpretation = (interpretations?.[0]?.interpretation ?? null) as
    | Record<string, unknown>
    | null;

  let autonomy_outcome: string | null = null;
  let governed_facts: Record<string, unknown> | null = null;
  if (interpretationId) {
    const { data: decisions } = await admin
      .from("whatsapp_order_autonomy_decisions")
      .select("autonomy_outcome, governed_facts")
      .eq("packet_id", packetId)
      .eq("interpretation_id", interpretationId)
      .order("evaluated_at", { ascending: false })
      .limit(1);
    autonomy_outcome = decisions?.[0]?.autonomy_outcome ?? null;
    governed_facts = (decisions?.[0]?.governed_facts ?? null) as
      | Record<string, unknown>
      | null;
  }

  const { data: cases } = await admin
    .from("whatsapp_communication_cases")
    .select("id, case_type, status, next_action")
    .eq("packet_id", packetId)
    .order("updated_at", { ascending: false })
    .limit(1);

  const { data: drafts } = await admin
    .from("sales_order_drafts")
    .select("id, status, promoted_order_id")
    .eq("packet_id", packetId)
    .order("created_at", { ascending: false })
    .limit(1);

  return {
    interpretation_id: interpretationId,
    interpretation,
    autonomy_outcome,
    governed_facts,
    case_id: cases?.[0]?.id ?? null,
    case_type: cases?.[0]?.case_type ?? null,
    case_status: cases?.[0]?.status ?? null,
    next_action: cases?.[0]?.next_action ?? null,
    draft_id: drafts?.[0]?.id ?? null,
    draft_status: drafts?.[0]?.status ?? null,
    promoted_order_id: drafts?.[0]?.promoted_order_id ?? null,
  };
}

export async function reconciliation(
  admin: SupabaseClient,
  runTag: string,
  packetIds: string[],
): Promise<Record<string, number>> {
  if (!packetIds.length) {
    return {
      orphan_raw_messages: 0,
      packets_without_case: 0,
      duplicate_drafts: 0,
      duplicate_promoted_orders: 0,
      unaccounted_potential_orders: 0,
    };
  }

  const prefix = `wa-s1b-${runTag}-`;
  const probeSuffixes = ["-gateb-clarify-probe", "-gatec-replay"];
  const { data: runRaw } = await admin
    .from("whatsapp_inbound_messages")
    .select("provider_message_id")
    .like("provider_message_id", `${prefix}%`);

  const providerIds = (runRaw ?? [])
    .map((r) => r.provider_message_id)
    .filter((id): id is string => Boolean(id))
    .filter((id) => !probeSuffixes.some((suffix) => id.endsWith(suffix)));
  let orphanRaw = 0;
  if (providerIds.length) {
    const { data: linked } = await admin
      .from("whatsapp_messages")
      .select("provider_message_id")
      .in("provider_message_id", providerIds);
    const linkedSet = new Set((linked ?? []).map((r) => r.provider_message_id));
    orphanRaw = providerIds.filter((id) => !linkedSet.has(id)).length;
  }

  let packetsWithoutCase = 0;
  for (const packetId of packetIds) {
    const { count } = await admin
      .from("whatsapp_communication_cases")
      .select("id", { count: "exact", head: true })
      .eq("packet_id", packetId);
    if (!count) packetsWithoutCase += 1;
  }

  let duplicateDrafts = 0;
  let duplicatePromotions = 0;
  for (const packetId of packetIds) {
    const { data: drafts } = await admin
      .from("sales_order_drafts")
      .select("id, promoted_order_id")
      .eq("packet_id", packetId);
    const draftCount = drafts?.length ?? 0;
    if (draftCount > 1) duplicateDrafts += draftCount - 1;
    const promoted = (drafts ?? []).filter((d) => d.promoted_order_id).length;
    if (promoted > 1) duplicatePromotions += promoted - 1;
  }

  const { data: reconRow, error: reconErr } = await admin
    .from("whatsapp_potential_order_reconciliation")
    .select("unaccounted_potential_orders")
    .maybeSingle();
  if (reconErr) {
    throw new Error(`RECONCILIATION_QUERY_FAILED:${reconErr.message}`);
  }

  return {
    orphan_raw_messages: orphanRaw,
    packets_without_case: packetsWithoutCase,
    duplicate_drafts: duplicateDrafts,
    duplicate_promoted_orders: duplicatePromotions,
    unaccounted_potential_orders: Number(reconRow?.unaccounted_potential_orders ?? 0),
  };
}

import type { SupabaseClient } from "npm:@supabase/supabase-js@2.95.0";
import { resolveInboundAtEdge } from "./resolveInboundAtEdge.ts";

export type StudioFanOutInput = {
  supabaseAdmin: SupabaseClient;
  providerMessageId: string;
  senderPhone: string;
  senderName: string | null;
  messageBody: string;
  messageType?: string;
  mediaCount?: number;
  conversationKey?: string | null;
  correctionOfProviderMessageId?: string | null;
  rawPayload: Record<string, unknown>;
  timestampSec: number | string | null;
  orderLikeHint: boolean;
  commercialRiskReason: string | null;
};

/**
 * Durable Studio/WA-1 ingest. Commercial-risk capture failures must reach the
 * webhook caller so the provider can retry; non-commercial fan-out remains best effort.
 */
export async function fanOutToStudioInbox(input: StudioFanOutInput): Promise<void> {
  const rawTrimmedBody = (input.messageBody ?? "").trim();
  const trimmedBody =
    rawTrimmedBody || `[unreadable ${input.messageType || "media"} attachment]`;
  if (!input.providerMessageId) {
    if (input.orderLikeHint) throw new Error("commercial WhatsApp message is missing provider message id");
    return;
  }

  if (input.orderLikeHint) {
    const { data: existingInbound, error: existingErr } = await input.supabaseAdmin
      .from("whatsapp_inbound_messages")
      .select("id")
      .eq("provider_message_id", input.providerMessageId)
      .maybeSingle();
    if (existingErr) {
      throw new Error(
        `commercial WhatsApp duplicate lookup failed: ${existingErr.message}`,
      );
    }
    if (existingInbound?.id) {
      // Retry after a partial downstream failure: continue into the governed
      // idempotent ingest/capture RPCs. Both correlate by provider_message_id
      // and return the existing persisted record when it was already captured.
      // Throwing here would trap the webhook in permanent 503 replay.
      console.log("[studio-fanout] existing commercial source; retry governed capture");
    }
  }

  let resolver_status: "resolved" | "pending" | "failed" = "pending";
  let resolver_result_json: Record<string, unknown> | null = null;

  try {
    const resolved = await resolveInboundAtEdge(input.supabaseAdmin, trimmedBody);
    if (resolved.resolver_status === "resolved" && resolved.resolver_result_json) {
      resolver_status = "resolved";
      resolver_result_json = resolved.resolver_result_json as unknown as Record<string, unknown>;
    } else if (resolved.resolver_status === "failed") {
      resolver_status = "failed";
    }
  } catch (e) {
    console.warn("[studio-fanout] resolver skipped:", e);
  }

  const tsSec =
    input.timestampSec != null && input.timestampSec !== "" ? Number(input.timestampSec) : NaN;
  const receivedAt =
    Number.isFinite(tsSec) && tsSec > 0 ? new Date(tsSec * 1000).toISOString() : new Date().toISOString();

  const { data: inbound, error } = await input.supabaseAdmin.rpc("ingest_whatsapp_inbound_message", {
    _provider_message_id: input.providerMessageId,
    _sender_phone: input.senderPhone,
    _sender_name: input.senderName,
    _message_body: trimmedBody,
    _message_type: input.messageType || "text",
    _received_at: receivedAt,
    _raw_payload: {
      ...input.rawPayload,
      studio_fanout: true,
      studio_fanout_source: "whatsapp-webhook-legacy",
      commercial_eligible: input.orderLikeHint,
      commercial_risk_reason: input.commercialRiskReason,
    },
    _resolver_status: resolver_status,
    _resolver_result_json: resolver_result_json,
  });

  if (error) {
    console.warn("[studio-fanout] ingest_whatsapp_inbound_message failed:", error.message);
    if (input.orderLikeHint) throw new Error(`commercial WhatsApp ingest failed: ${error.message}`);
    return;
  }

  const inboundRow = Array.isArray(inbound) ? inbound[0] : inbound;
  if (input.orderLikeHint && !inboundRow?.id) {
    throw new Error("commercial WhatsApp ingest returned no inbound message id");
  }
  if (inboundRow?.id && input.orderLikeHint) {
    const mediaCount = Math.max(0, input.mediaCount ?? 0);
    const unreadableMedia =
      rawTrimmedBody === "" && (input.messageType || "text") !== "text";
    const resolvedWithoutProduct =
      resolver_status === "resolved" && !resolver_result_json?.resolved_product_id;
    const awaitingMediaReview = unreadableMedia && mediaCount > 0;
    // Empty-body multimodal ingress is AWAITING_MEDIA until download/worker
    // completes. Do not terminalize as FAILED_INTERPRETATION at capture.
    const interpretationFailed = awaitingMediaReview
      ? false
      : resolvedWithoutProduct || (unreadableMedia && mediaCount === 0);
    let correctionSourceId: string | null = null;
    if (input.correctionOfProviderMessageId) {
      const correctionSource = await input.supabaseAdmin
        .from("whatsapp_inbound_messages")
        .select("id")
        .eq("provider_message_id", input.correctionOfProviderMessageId)
        .maybeSingle();
      correctionSourceId = correctionSource.data?.id ?? null;
    }
    const interpretationFailureKind = interpretationFailed
      ? unreadableMedia
        ? "UNREADABLE_MEDIA"
        : resolvedWithoutProduct
        ? "UNRESOLVED_PRODUCT"
        : null
      : awaitingMediaReview
      ? "AWAITING_MEDIA_REVIEW"
      : null;
    const { error: captureError } = await input.supabaseAdmin.rpc("capture_whatsapp_commercial_fragment", {
      p_source_message_id: inboundRow.id,
      p_packet_id: null,
      p_conversation_key: input.conversationKey,
      p_correction_of_source_message_id: correctionSourceId,
      p_media_count: mediaCount,
      p_interpretation_failed: interpretationFailed,
      p_evidence: {
        ingress: "whatsapp-webhook",
        resolver_status,
        commercial_risk_reason: input.commercialRiskReason,
        fail_open_media_review: awaitingMediaReview ? true : undefined,
        interpretation_failure_kind: interpretationFailureKind,
      },
    });
    if (captureError) {
      console.warn("[studio-fanout] potential-order capture failed:", captureError.message);
      throw new Error(`commercial potential-order capture failed: ${captureError.message}`);
    }
  }
}

import type { SupabaseClient } from "npm:@supabase/supabase-js@2.95.0";
import { loadCatalogForEdge } from "./catalogLoader.ts";
import { resolveProductUtterance } from "./runtime/resolveProductUtterance.ts";
import type { ProductUtteranceResolution } from "./runtime/types.ts";

export type EdgeResolveResult = {
  resolver_status: "resolved" | "failed";
  resolver_result_json: ProductUtteranceResolution | null;
};

export async function resolveInboundAtEdge(
  admin: SupabaseClient,
  messageBody: string,
): Promise<EdgeResolveResult> {
  try {
    const catalog = await loadCatalogForEdge(admin);
    const resolution = resolveProductUtterance(messageBody, catalog);
    return {
      resolver_status: "resolved",
      resolver_result_json: resolution,
    };
  } catch {
    return {
      resolver_status: "failed",
      resolver_result_json: null,
    };
  }
}

import type { SupabaseClient } from "npm:@supabase/supabase-js@2.95.0";
import type { RuntimeCatalog, RuntimeCatalogAlias, RuntimeCatalogProduct } from "./runtime/types.ts";

function aliasTextFromRow(row: Record<string, unknown>): string {
  const primary = row.alias ?? row.alias_text;
  return String(primary ?? "").trim();
}

function canonicalFromRow(row: Record<string, unknown>, fallback: string): string {
  const c = row.canonical_name;
  return (typeof c === "string" && c.trim()) || fallback;
}

/** Bulk catalogue loader for edge webhook resolver (read-only). */
export async function loadCatalogForEdge(admin: SupabaseClient): Promise<RuntimeCatalog> {
  const { data: products, error: productsError } = await admin
    .from("products")
    .select(
      "id, sku, name, product_name, short_name, category, subcategory, packaging_code, is_active, created_at",
    );

  if (productsError) throw productsError;

  const mappedProducts: RuntimeCatalogProduct[] = (products ?? []).map((p) => ({
    id: p.id,
    sku: p.sku,
    name: p.name ?? p.product_name ?? "Unnamed product",
    product_name: p.product_name ?? null,
    short_name: p.short_name ?? null,
    category: p.category ?? null,
    subcategory: p.subcategory ?? null,
    packaging_code: p.packaging_code ?? null,
    is_active: p.is_active ?? null,
    archived_at: null,
    created_at: p.created_at ?? null,
    updated_at: null,
  }));

  const { data: aliasRows, error: aliasError } = await admin
    .from("product_aliases")
    .select("product_id, alias_text, canonical_name, created_at");

  if (aliasError) throw aliasError;

  const aliases: RuntimeCatalogAlias[] = [];
  for (const row of aliasRows ?? []) {
    const product = mappedProducts.find((p) => p.id === row.product_id);
    if (!product) continue;
    const alias_text = aliasTextFromRow(row as Record<string, unknown>);
    if (!alias_text) continue;
    aliases.push({
      alias_text,
      canonical_name: canonicalFromRow(row as Record<string, unknown>, product.name),
      product_id: row.product_id,
      alias_type: null,
    });
  }

  return { products: mappedProducts, aliases };
}

import { buildCatalogLexicon, type CatalogLexiconEntry } from "./catalogLexicon.ts";
import { collapseCandidatesByLogicalGroup } from "./candidateGrouping.ts";
import { cashewTartFamilyConfidenceBoost } from "./productFamilies.ts";
import {
  actionForBand,
  assignConfidenceBand,
  buildReason,
  isAmbiguous,
} from "./confidenceBands.ts";
import { normalizeUtterance } from "./normalizeUtterance.ts";
import { extractOrderQuantity } from "./parseOrderQuantity.ts";
import {
  bulkPhraseBoost,
  cheeseIntentBoost,
  exactSkuScore,
  exactUtteranceAliasBoost,
  frozenIntentBoost,
  packCountBoost,
  tokenOverlapScore,
} from "./scoring.ts";
import type {
  MatchSource,
  ProductUtteranceResolution,
  RuntimeAlternative,
  RuntimeCatalog,
  RuntimeResolverConfig,
} from "./types.ts";
import { DEFAULT_RUNTIME_RESOLVER_CONFIG } from "./types.ts";

type ScoredCandidate = {
  product_id: string;
  sku: string;
  product_name: string;
  matched_term: string;
  match_source: MatchSource;
  confidence: number;
};

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((t) => t.trim())
    .filter(Boolean);
}

function pickExactAliasWinner(
  catalog: RuntimeCatalog,
  ranked: ScoredCandidate[],
  raw: string,
): ScoredCandidate | undefined {
  const r = raw.trim().toLowerCase().replace(/\s+/g, " ");

  for (const alias of catalog.aliases) {
    const aliasText = alias.alias_text.trim().toLowerCase().replace(/\s+/g, " ");
    if (aliasText !== r) continue;
    const rankedMatch = ranked.find((c) => c.product_id === alias.product_id);
    if (rankedMatch) {
      return {
        ...rankedMatch,
        matched_term: alias.alias_text,
        match_source: "alias",
      };
    }
  }

  const rSorted = [...r.split(/\s+/)].sort().join(" ");
  const sortedMatches = ranked.filter((c) => {
    if (c.match_source !== "alias" && c.match_source !== "short_name") return false;
    const tSorted = [...c.matched_term.trim().toLowerCase().split(/\s+/)].sort().join(" ");
    return tSorted === rSorted;
  });
  return sortedMatches.length === 1 ? sortedMatches[0] : undefined;
}

function considerCandidate(map: Map<string, ScoredCandidate>, candidate: ScoredCandidate) {
  const existing = map.get(candidate.product_id);
  if (!existing || candidate.confidence > existing.confidence) {
    map.set(candidate.product_id, candidate);
  }
}

function scoreEntryTerms(
  entry: CatalogLexiconEntry,
  normalized: ReturnType<typeof normalizeUtterance>,
  catalog: RuntimeCatalog,
): ScoredCandidate | null {
  const queryVariants = [
    normalized.normalized_text,
    normalized.alias_match_text,
    normalized.tokens.join(" "),
  ].filter(Boolean);

  let best: ScoredCandidate | null = null;

  for (const term of entry.terms) {
    let score = 0;

    if (term.source === "sku") {
      score = Math.max(...queryVariants.map((q) => exactSkuScore(q, term.text)));
    } else {
      for (const qv of queryVariants) {
        const qTokens = tokenize(qv);
        const overlap = tokenOverlapScore(qTokens.length ? qTokens : normalized.tokens, term.tokens);
        score = Math.max(score, overlap);
      }
    }

    if (score <= 0) continue;

    let capped =
      term.source === "sku"
        ? score
        : Math.min(0.97, score + (term.source === "alias" ? 0.02 : 0));

    if (term.source === "alias") {
      capped = Math.min(1, capped + exactUtteranceAliasBoost(normalized.raw, term.text));
    }
    capped = Math.min(1, capped + bulkPhraseBoost(normalized.raw, entry.resolved_name, entry.sku));

    const candidate: ScoredCandidate = {
      product_id: entry.product_id,
      sku: entry.sku,
      product_name: entry.resolved_name,
      matched_term: term.text,
      match_source: term.source,
      confidence: capped,
    };

    if (!best || candidate.confidence > best.confidence) {
      best = candidate;
    }
  }

  if (!best) return null;

  let confidence = best.confidence;
  confidence += packCountBoost(normalized.pack_count, entry.search_text, entry.sku);
  confidence += frozenIntentBoost(normalized.tokens, entry.search_text);
  confidence += cheeseIntentBoost(normalized.tokens, entry.search_text);
  const product = catalog.products.find((p) => p.id === entry.product_id);
  if (product) {
    confidence += cashewTartFamilyConfidenceBoost(normalized.raw, product);
  }
  confidence = Math.min(1, Math.max(0, confidence));

  return { ...best, confidence };
}

function isMidyaSingleTokenAmbiguous(
  normalized: ReturnType<typeof normalizeUtterance>,
  catalog: RuntimeCatalog,
): boolean {
  if (normalized.pack_count) return false;
  if (normalized.tokens.length !== 1) return false;
  const token = normalized.tokens[0];
  if (!["midya", "midea", "mediya"].includes(token)) return false;

  const midyaProducts = catalog.products.filter((p) => p.name.toLowerCase().includes("midya"));
  const bulk = midyaProducts.filter((p) => p.name.toLowerCase().includes("bulk"));
  const gift = midyaProducts.filter(
    (p) => p.name.toLowerCase().includes("gift pack") || p.name.toLowerCase().includes("maapet"),
  );
  return bulk.length >= 1 && gift.length >= 1;
}

function isNutAsiyahAmbiguous(
  normalized: ReturnType<typeof normalizeUtterance>,
  catalog: RuntimeCatalog,
): boolean {
  const tokens = normalized.tokens;
  if (tokens.length !== 2) return false;

  const isAsiyah = (t: string) => ["asiyah", "assiyah", "assiya"].includes(t);
  const isCashew = (t: string) => ["cashew", "kaju"].includes(t);
  const isPistachio = (t: string) => ["pistachio", "pista"].includes(t);

  // Dedicated alias order e.g. "assiyah pista" — resolved via exact alias, not generic ambiguity.
  if (isAsiyah(tokens[0]) && (isCashew(tokens[1]) || isPistachio(tokens[1]))) {
    return false;
  }

  if (!isAsiyah(tokens[1])) return false;
  const wantsCashew = isCashew(tokens[0]);
  const wantsPistachio = isPistachio(tokens[0]);
  if (!wantsCashew && !wantsPistachio) return false;

  const qualifiers = ["mor", "chocolate", "beetroot"];
  if (qualifiers.some((q) => normalized.normalized_text.includes(q))) return false;

  const asiyahProducts = catalog.products.filter((p) => {
    const name = p.name.toLowerCase();
    if (!name.includes("asiyah")) return false;
    if (wantsCashew && name.includes("cashew")) return true;
    if (wantsPistachio && name.includes("pistachio")) return true;
    return false;
  });

  return asiyahProducts.length >= 2;
}

/**
 * Phase 2A identify-only resolver — read-only catalogue, no writes.
 */
export function resolveProductUtterance(
  input: string,
  catalog: RuntimeCatalog,
  config: RuntimeResolverConfig = DEFAULT_RUNTIME_RESOLVER_CONFIG,
): ProductUtteranceResolution {
  const normalized = normalizeUtterance(input);
  const lexicon = buildCatalogLexicon(catalog);
  const candidateMap = new Map<string, ScoredCandidate>();

  if (!normalized.normalized_text) {
    return {
      query: input,
      normalized_text: "",
      resolved_product_id: null,
      resolved_sku: null,
      resolved_name: null,
      confidence: 0,
      confidence_band: "LOW",
      action: "ask_clarification",
      reason: "No product matched the normalized utterance.",
      clarification_required: true,
      alternatives: [],
      pack_count: normalized.pack_count,
      order_quantity: extractOrderQuantity(input),
    };
  }

  for (const entry of lexicon) {
    const scored = scoreEntryTerms(entry, normalized, catalog);
    if (scored) considerCandidate(candidateMap, scored);
  }

  let ranked = Array.from(candidateMap.values()).sort((a, b) => b.confidence - a.confidence);
  const {
    collapsed: logicalRanked,
    rawCount,
    logicalGroupCount,
    collapsedDuplicateCount,
  } = collapseCandidatesByLogicalGroup(ranked, catalog, normalized.raw);
  ranked = logicalRanked;

  const midyaAmbiguous = isMidyaSingleTokenAmbiguous(normalized, catalog);
  const exactWinner = midyaAmbiguous ? undefined : pickExactAliasWinner(catalog, ranked, normalized.raw);
  const top = exactWinner ?? ranked[0];
  const second = exactWinner
    ? ranked.find((r) => r.product_id !== exactWinner.product_id)
    : ranked[1];

  const asiyahAmbiguous = isNutAsiyahAmbiguous(normalized, catalog);
  const deltaAmbiguous =
    !exactWinner && top && second
      ? isAmbiguous(top.confidence, second.confidence, config.ambiguity_delta)
      : false;

  const ambiguous = !exactWinner && (midyaAmbiguous || asiyahAmbiguous || deltaAmbiguous);
  const hasCandidates = ranked.length > 0;
  let confidence = top?.confidence ?? 0;

  if (ambiguous && top) {
    confidence = Math.min(confidence, config.min_threshold - 0.01);
  }

  const confidence_band = assignConfidenceBand(
    confidence,
    ambiguous,
    hasCandidates,
    config.high_threshold,
    config.min_threshold,
  );
  const action = actionForBand(confidence_band);
  const clarification_required = action === "ask_clarification";

  const alternatives: RuntimeAlternative[] = ranked.slice(0, config.max_candidates).map((r) => ({
    product_id: r.product_id,
    sku: r.sku,
    product_name: r.product_name,
    confidence: Number(r.confidence.toFixed(4)),
    matched_term: r.matched_term,
    match_source: r.match_source,
  }));

  const reason = buildReason({
    band: confidence_band,
    ambiguous,
    confidence,
    minThreshold: config.min_threshold,
    matchSource: top?.match_source,
    matchedTerm: top?.matched_term,
    resolvedSku: clarification_required ? null : top?.sku,
    candidateCount: rawCount,
    logicalGroupCount,
    collapsedDuplicateCount,
  });

  return {
    query: input,
    normalized_text: normalized.normalized_text,
    resolved_product_id: clarification_required ? null : (top?.product_id ?? null),
    resolved_sku: clarification_required ? null : (top?.sku ?? null),
    resolved_name: clarification_required ? null : (top?.product_name ?? null),
    confidence: Number(confidence.toFixed(4)),
    confidence_band,
    action,
    reason,
    clarification_required,
    alternatives,
    pack_count: normalized.pack_count,
    order_quantity: extractOrderQuantity(input),
  };
}

import type { RuntimeCatalog, RuntimeCatalogAlias, RuntimeCatalogProduct } from "./types.ts";

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((t) => t.trim())
    .filter(Boolean);
}

export type CatalogLexiconEntry = {
  product_id: string;
  sku: string;
  resolved_name: string;
  search_text: string;
  name_tokens: string[];
  terms: Array<{ text: string; tokens: string[]; source: "sku" | "name" | "short_name" | "alias" | "canonical_name" | "category" | "subcategory" }>;
};

export function buildCatalogLexicon(catalog: RuntimeCatalog): CatalogLexiconEntry[] {
  const aliasesByProduct = new Map<string, RuntimeCatalogAlias[]>();
  for (const alias of catalog.aliases) {
    const list = aliasesByProduct.get(alias.product_id) ?? [];
    list.push(alias);
    aliasesByProduct.set(alias.product_id, list);
  }

  return catalog.products.map((product) => {
    const resolved_name = product.product_name ?? product.name;
    const terms: CatalogLexiconEntry["terms"] = [];

    const addTerm = (text: string, source: CatalogLexiconEntry["terms"][number]["source"]) => {
      const trimmed = text.trim();
      if (!trimmed) return;
      terms.push({ text: trimmed, tokens: tokenize(trimmed), source });
    };

    addTerm(product.sku, "sku");
    addTerm(product.name, "name");
    if (product.product_name) addTerm(product.product_name, "name");
    if (product.short_name) addTerm(product.short_name, "short_name");
    if (product.category) addTerm(product.category, "category");
    if (product.subcategory) addTerm(product.subcategory, "subcategory");

    for (const alias of aliasesByProduct.get(product.id) ?? []) {
      addTerm(alias.alias_text, "alias");
      addTerm(alias.canonical_name, "canonical_name");
    }

    const search_text = [
      product.sku,
      product.name,
      product.product_name,
      product.short_name,
      product.category,
      product.subcategory,
      ...(aliasesByProduct.get(product.id) ?? []).flatMap((a) => [a.alias_text, a.canonical_name]),
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    return {
      product_id: product.id,
      sku: product.sku,
      resolved_name,
      search_text,
      name_tokens: tokenize(resolved_name),
      terms,
    };
  });
}

import { productFamilyKey } from "./productFamilies.ts";
import type { RuntimeCatalog, RuntimeCatalogProduct } from "./types.ts";

export type ScoredCandidateLike = {
  product_id: string;
  sku: string;
  product_name: string;
  matched_term: string;
  match_source: string;
  confidence: number;
};

export type CollapsedCandidatesResult<T extends ScoredCandidateLike> = {
  collapsed: T[];
  rawCount: number;
  logicalGroupCount: number;
  collapsedDuplicateCount: number;
};

function normalizeLabel(value: string | null | undefined): string {
  return (value ?? "").trim().toLowerCase().replace(/\s+/g, " ");
}

/** Extract trailing numeric serial from Oasis SKUs e.g. ...-0017 → 17 */
export function skuSerial(sku: string): number {
  const match = sku.match(/(\d+)\s*$/);
  return match ? Number(match[1]) : 0;
}

/** Pack / variant bucket so bulk vs gift remain distinct logical groups. */
export function packVariantIndicator(product: RuntimeCatalogProduct): string {
  const hay = [
    product.sku,
    product.name,
    product.product_name,
    product.short_name,
    product.packaging_code,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  if (hay.includes("gift pack") || hay.includes("gift") && hay.includes("pc")) return "gift_pack";
  if (product.sku.includes("MAAPET") || hay.includes("maapet")) return "maapet";
  if (product.sku.includes("BULK") || hay.includes(" bulk")) return "bulk";
  if (product.packaging_code) return normalizeLabel(product.packaging_code);

  const skuSegment = product.sku.split("-").find((s) =>
    ["BULK", "MAAPET", "LOOSE", "TRAY1KG", "RBOX", "MAPTRAY"].includes(s.toUpperCase()),
  );
  if (skuSegment) return skuSegment.toLowerCase();

  return "default";
}

/** Stable logical group key — duplicate catalogue rows share this key. */
export function logicalGroupKey(product: RuntimeCatalogProduct): string {
  const family = productFamilyKey(product);
  if (family) {
    return `family::${family}`;
  }

  const name = normalizeLabel(product.product_name ?? product.name);
  const short = normalizeLabel(product.short_name);
  const category = normalizeLabel(product.category);
  const subcategory = normalizeLabel(product.subcategory);
  const pack = packVariantIndicator(product);
  return [name, short, category, subcategory, pack].join("::");
}

function isActiveProduct(product: RuntimeCatalogProduct | undefined): boolean {
  if (!product) return false;
  if (product.archived_at) return false;
  if (product.is_active === false) return false;
  return true;
}

function timestampMs(value: string | null | undefined): number {
  if (!value) return 0;
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? ms : 0;
}

function exactAliasMatchScore(rawUtterance: string, matchedTerm: string): number {
  const raw = rawUtterance.trim().toLowerCase().replace(/\s+/g, " ");
  const term = matchedTerm.trim().toLowerCase().replace(/\s+/g, " ");
  if (raw === term) return 2;
  const rawSorted = [...raw.split(" ")].sort().join(" ");
  const termSorted = [...term.split(" ")].sort().join(" ");
  return rawSorted === termSorted ? 1 : 0;
}

function compareRepresentatives<T extends ScoredCandidateLike>(
  a: T,
  b: T,
  productA: RuntimeCatalogProduct | undefined,
  productB: RuntimeCatalogProduct | undefined,
  rawUtterance: string,
): number {
  const activeA = isActiveProduct(productA) ? 1 : 0;
  const activeB = isActiveProduct(productB) ? 1 : 0;
  if (activeA !== activeB) return activeB - activeA;

  const updatedA = Math.max(timestampMs(productA?.updated_at), timestampMs(productA?.created_at));
  const updatedB = Math.max(timestampMs(productB?.updated_at), timestampMs(productB?.created_at));
  if (updatedA !== updatedB) return updatedB - updatedA;

  const serialA = skuSerial(a.sku);
  const serialB = skuSerial(b.sku);
  if (serialA !== serialB) return serialB - serialA;

  if (a.confidence !== b.confidence) return b.confidence - a.confidence;

  const aliasA = exactAliasMatchScore(rawUtterance, a.matched_term);
  const aliasB = exactAliasMatchScore(rawUtterance, b.matched_term);
  if (aliasA !== aliasB) return aliasB - aliasA;

  return a.sku.localeCompare(b.sku);
}

function pickGroupRepresentative<T extends ScoredCandidateLike>(
  group: T[],
  productById: Map<string, RuntimeCatalogProduct>,
  rawUtterance: string,
): T {
  return [...group].sort((a, b) =>
    compareRepresentatives(a, b, productById.get(a.product_id), productById.get(b.product_id), rawUtterance),
  )[0];
}

/**
 * Collapse duplicate/near-duplicate catalogue rows into one representative per logical group.
 * Ambiguity checks should run on collapsed groups, not raw product rows.
 */
export function collapseCandidatesByLogicalGroup<T extends ScoredCandidateLike>(
  candidates: T[],
  catalog: RuntimeCatalog,
  rawUtterance: string,
): CollapsedCandidatesResult<T> {
  const productById = new Map(catalog.products.map((p) => [p.id, p]));
  const byGroup = new Map<string, T[]>();

  for (const candidate of candidates) {
    const product = productById.get(candidate.product_id);
    const key = product ? logicalGroupKey(product) : `unknown::${candidate.product_id}`;
    const list = byGroup.get(key) ?? [];
    list.push(candidate);
    byGroup.set(key, list);
  }

  const collapsed: T[] = [];
  for (const group of byGroup.values()) {
    collapsed.push(pickGroupRepresentative(group, productById, rawUtterance));
  }

  collapsed.sort((a, b) => b.confidence - a.confidence);

  return {
    collapsed,
    rawCount: candidates.length,
    logicalGroupCount: collapsed.length,
    collapsedDuplicateCount: candidates.length - collapsed.length,
  };
}

import type { RuntimeCatalogProduct } from "./types.ts";

/** Accepted SKUs for the Cashew Tart / Tart Cashew product family. */
export const CASHEW_TART_FAMILY_SKUS = [
  "OAS-AS-BKL-0020",
  "OAS-AS-BKL-CSH-BULK-0003",
  "OAS-AS-BKL-CSH-BULK-0004",
] as const;

const CASHEW_TOKENS = new Set(["cashew", "kaju"]);
const TART_TOKENS = new Set(["tart"]);

function nameTokens(product: RuntimeCatalogProduct): string[] {
  return [product.name, product.product_name, product.short_name]
    .filter(Boolean)
    .join(" ")
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((t) => t.trim())
    .filter(Boolean);
}

/** True when catalogue row is Cashew Tart / Tart Cashew (any pack variant). */
export function isCashewTartFamilyProduct(product: RuntimeCatalogProduct): boolean {
  return productFamilyKey(product) === "cashew_tart";
}

export function isCashewTartFamilySku(sku: string | null | undefined): boolean {
  if (!sku) return false;
  return (CASHEW_TART_FAMILY_SKUS as readonly string[]).includes(sku);
}

/**
 * Canonical product-family key for equivalent identity rows.
 * cashew tart = tart cashew = kaju tart = tart kaju → one family.
 */
export function productFamilyKey(product: RuntimeCatalogProduct): string | null {
  const tokens = nameTokens(product);
  const hasCashew = tokens.some((t) => CASHEW_TOKENS.has(t));
  const hasTart = tokens.some((t) => TART_TOKENS.has(t));
  if (hasCashew && hasTart) return "cashew_tart";
  return null;
}

/** Order-independent alias phrases equivalent within the cashew tart family. */
export function isCashewTartFamilyUtterance(text: string): boolean {
  const tokens = text
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter(Boolean);
  if (tokens.length < 2) return false;
  const hasCashew = tokens.some((t) => CASHEW_TOKENS.has(t));
  const hasTart = tokens.some((t) => TART_TOKENS.has(t));
  return hasCashew && hasTart;
}

export function cashewTartFamilyConfidenceBoost(
  rawUtterance: string,
  product: RuntimeCatalogProduct,
): number {
  if (!isCashewTartFamilyUtterance(rawUtterance)) return 0;
  if (!isCashewTartFamilyProduct(product)) return 0;
  return 0.14;
}

import type { ConfidenceBand, ResolverAction } from "./types.ts";

export function isAmbiguous(top: number, second: number | undefined, delta: number): boolean {
  return second != null && top - second < delta;
}

export function assignConfidenceBand(
  confidence: number,
  ambiguous: boolean,
  hasCandidates: boolean,
  highThreshold: number,
  minThreshold: number,
): ConfidenceBand {
  if (!hasCandidates || confidence < minThreshold || ambiguous) return "LOW";
  if (confidence >= highThreshold) return "HIGH";
  return "MEDIUM";
}

export function actionForBand(band: ConfidenceBand): ResolverAction {
  switch (band) {
    case "HIGH":
      return "auto_suggest";
    case "MEDIUM":
      return "operator_review";
    default:
      return "ask_clarification";
  }
}

export function buildReason(opts: {
  band: ConfidenceBand;
  ambiguous: boolean;
  confidence: number;
  minThreshold: number;
  matchSource?: string;
  matchedTerm?: string;
  resolvedSku?: string | null;
  candidateCount: number;
  logicalGroupCount?: number;
  collapsedDuplicateCount?: number;
}): string {
  const {
    band,
    ambiguous,
    confidence,
    minThreshold,
    matchSource,
    matchedTerm,
    resolvedSku,
    candidateCount,
    logicalGroupCount,
    collapsedDuplicateCount = 0,
  } = opts;

  const groupCount = logicalGroupCount ?? candidateCount;

  if (candidateCount === 0) {
    return "No product matched the normalized utterance.";
  }
  if (ambiguous) {
    if (collapsedDuplicateCount > 0) {
      return `Multiple product groups score within ambiguity delta — ${groupCount} group(s) need clarification (duplicate catalogue rows collapsed).`;
    }
    return `Multiple product groups score within ambiguity delta — ${groupCount} group(s) need clarification.`;
  }
  if (collapsedDuplicateCount > 0 && band === "HIGH") {
    if (resolvedSku && matchSource === "sku") {
      return `Matched SKU exactly: ${resolvedSku} (duplicate catalogue rows collapsed into product groups).`;
    }
    if (matchedTerm && matchSource) {
      return `Matched via ${matchSource}: "${matchedTerm}" (${band} confidence ${confidence.toFixed(2)}; duplicate catalogue rows collapsed).`;
    }
  }
  if (confidence < minThreshold) {
    return `Best confidence ${confidence.toFixed(2)} is below ${minThreshold} threshold.`;
  }
  if (resolvedSku && matchSource === "sku") {
    return `Matched SKU exactly: ${resolvedSku}`;
  }
  if (matchedTerm && matchSource) {
    return `Matched via ${matchSource}: "${matchedTerm}" (${band} confidence ${confidence.toFixed(2)})`;
  }
  return `Resolved with ${band} confidence ${confidence.toFixed(2)}`;
}

import { applyPhraseSynonyms } from "./synonymMap.ts";

const FILLERS = new Set([
  "pls",
  "please",
  "want",
  "need",
  "order",
  "give",
  "send",
  "one",
  "some",
  "the",
  "a",
  "an",
  "of",
  "for",
  "me",
  "mujhe",
  "chahiye",
  "dedo",
  "bhejo",
  "kilo",
  "kg",
  "gram",
  "gms",
]);

const UNIT_NOISE = new Set(["pc", "pcs", "piece", "pieces", "pkt", "pack"]);

export interface NormalizedUtterance {
  raw: string;
  normalized_text: string;
  tokens: string[];
  pack_count: number | null;
  /** Retains pack qty for alias matching e.g. "6 pc midya". */
  alias_match_text: string;
}

const SKU_PATTERN = /^OAS-[A-Z0-9-]+$/i;

export function extractPackCount(text: string): number | null {
  const packMatch = text.match(/\b(\d{1,3})\s*(?:pc|pcs|piece|pieces)\b/i);
  return packMatch ? Number(packMatch[1]) : null;
}

export function normalizeUtterance(raw: string): NormalizedUtterance {
  const trimmed = raw.trim();
  if (SKU_PATTERN.test(trimmed)) {
    return {
      raw: trimmed,
      normalized_text: trimmed.toUpperCase(),
      tokens: [trimmed.toUpperCase()],
      pack_count: null,
      alias_match_text: trimmed.toUpperCase(),
    };
  }

  let text = trimmed.toLowerCase();
  text = applyPhraseSynonyms(text);

  let pack_count: number | null = null;
  const packMatch = text.match(/\b(\d{1,3})\s*(?:pc|pcs|piece|pieces)\b/);
  const alias_match_text = packMatch ? text.trim() : text.trim();
  if (packMatch) {
    pack_count = Number(packMatch[1]);
    text = text.replace(packMatch[0], " ").trim();
  }

  const tokens = text
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((t) => t.trim())
    .filter((t) => t.length > 0 && !FILLERS.has(t) && !UNIT_NOISE.has(t));

  return {
    raw: trimmed,
    normalized_text: tokens.join(" "),
    tokens,
    pack_count,
    alias_match_text: alias_match_text.replace(/[^a-z0-9\s-]/g, " ").replace(/\s+/g, " ").trim(),
  };
}

/** Static additive synonym config — no DB migration. */
